<script>
  import {onMount,onDestroy} from 'svelte';import {get} from 'svelte/store';import {client,createLoader,isAbort} from '../lib/api.js';import Button from '../components/Button.svelte';import Icon from '../components/Icon.svelte';import Notice from '../components/Notice.svelte';import Secret from '../components/Secret.svelte';import Confirm from '../components/Confirm.svelte';
  export let lang='vi';const resource=createLoader();let form=null,password='',error='',success='',busy='',confirm=null,alive=true;
  $: t=(vi,en)=>lang==='en'?en:vi;
  const me=get(client.session).account?.id;
  function load(){return resource.load(signal=>client.request('/v1/admin/accounts',{signal}));}
  function edit(account=null,reset=false){password='';error='';form={id:account?.id||null,email:account?.email||'',name:account?.name||'',phone:account?.phone||'',is_admin:account?.is_admin||false,reset};}
  async function run(key,fn){if(busy)return;busy=key;error='';success='';try{await client.mutate(`account:${key}`,fn);}catch(e){if(alive&&!isAbort(e))error=e.message;}finally{if(alive)busy='';}}
  function save(){const account={...form},pw=password;run('save',async()=>{const body=account.reset?{password:pw}:{name:account.name||null,phone:account.phone||null,is_admin:account.is_admin,...(!account.id?{email:account.email.trim(),password:pw}:{})};await client.request(`/v1/admin/accounts${account.id?`/${account.id}`:''}`,{method:account.id?'PATCH':'POST',body});if(alive){password='';form=null;success=t('Đã lưu tài khoản.','Account saved.');load();}});}
  function toggle(account){run(`toggle:${account.id}`,async()=>{await client.request(`/v1/admin/accounts/${account.id}`,{method:'PATCH',body:{active:!account.active}});if(alive)load();});}
  function remove(account){confirm={title:t('Xoá tài khoản','Delete account'),message:t('Tài khoản sẽ bị xoá. Các bảng được giữ theo chính sách máy chủ.','The account will be deleted. Tables follow the server retention policy.'),phrase:account.email,fn:()=>run(`delete:${account.id}`,async()=>{await client.request(`/v1/admin/accounts/${account.id}`,{method:'DELETE'});if(alive){confirm=null;load();}})};}
  const hide=()=>{if(document.hidden)password='';};
  onMount(()=>{load();document.addEventListener('visibilitychange',hide);});onDestroy(()=>{alive=false;password='';resource.dispose();document.removeEventListener('visibilitychange',hide);});
</script>
<Notice {error} {success} {lang}/>
<section class="panel"><div class="flex flex-wrap items-center justify-between gap-4 mb-5"><div><h2>{t('Tài khoản trong hệ thống','System accounts')}</h2><p class="text-muted text-xs mt-2">{t('Quản lý quyền truy cập và thông tin tài khoản.','Manage account details and access.')}</p></div><div class="flex gap-2"><Button busy={$resource.loading} on:click={load}><Icon name="refresh" size={16}/></Button><Button variant="primary" on:click={()=>edit()}><Icon name="plus" size={17}/>{t('Thêm tài khoản','Add account')}</Button></div></div><Notice error={$resource.error} retry={load} {lang}/>
  {#if $resource.loading&&!$resource.data}<div class="empty" role="status">{t('Đang tải tài khoản…','Loading accounts…')}</div>{/if}
  <div class="divide-y divide-line" aria-busy={$resource.loading}>{#each $resource.data||[] as account (account.id)}<div class="py-5 flex flex-wrap gap-5 justify-between items-center"><div class="flex gap-3 items-start min-w-0"><div class="account-avatar">{#if account.avatar_url}<img src={account.avatar_url} alt="" width="40" height="40" referrerpolicy="no-referrer"/>{:else}{(account.name||account.email)[0].toUpperCase()}{/if}</div><div class="min-w-0"><b class="break-all">{account.name||account.email}{#if account.id===me}<span class="text-xs text-muted ml-2">{t('(bạn)','(you)')}</span>{/if}</b><p class="text-xs text-muted break-all">{account.email}</p><div class="flex gap-2 flex-wrap mt-2"><span class="badge">{account.is_admin?'Admin':t('Người dùng','User')}</span><span class="badge" class:ok={account.active} class:bad={!account.active}>{account.active?t('Đang hoạt động','Active'):t('Đã khoá','Disabled')}</span>{#if account.via_google}<span class="badge">Google</span>{/if}<span class="text-xs text-muted">{account.n_tables} {t('bảng','tables')} {account.phone?' · '+account.phone:''}</span></div></div></div><div class="flex gap-2 flex-wrap"><Button disabled={!!busy} on:click={()=>edit(account)}>{t('Sửa','Edit')}</Button><Button disabled={!!busy} on:click={()=>edit(account,true)}>{t('Đặt mật khẩu','Set password')}</Button>{#if account.id!==me}<Button disabled={!!busy} on:click={()=>toggle(account)}>{account.active?t('Khoá','Disable'):t('Mở khoá','Enable')}</Button><Button variant="ghost" label={`${t('Xoá tài khoản','Delete account')} ${account.email}`} disabled={!!busy} on:click={()=>remove(account)}><Icon name="trash" size={16}/></Button>{/if}</div></div>{/each}</div>
</section>
{#if form}<section class="panel mt-5"><div class="flex justify-between items-center mb-5"><h2>{form.reset?t('Đặt mật khẩu','Set password'):form.id?t('Sửa tài khoản','Edit account'):t('Thêm tài khoản','Add account')}</h2><Button variant="ghost" label={t('Đóng','Close')} on:click={()=>{form=null;password='';}}><Icon name="close"/></Button></div><form on:submit|preventDefault={save}><div class="grid sm:grid-cols-2 gap-4">{#if !form.reset}<label class="field"><span>Email</span><input type="email" bind:value={form.email} required readonly={!!form.id}/></label><label class="field"><span>{t('Tên','Name')}</span><input bind:value={form.name}/></label><label class="field"><span>{t('Số điện thoại','Phone')}</span><input type="tel" bind:value={form.phone}/></label>{/if}{#if !form.id||form.reset}<Secret bind:value={password} label={t('Mật khẩu mới (ít nhất 6 ký tự)','New password (at least 6 characters)')} autocomplete="new-password" minlength="6" required {lang}/>{/if}</div>{#if !form.reset}<label class="flex gap-2 items-center text-sm mt-5"><input type="checkbox" bind:checked={form.is_admin} disabled={form.id===me}/>{t('Quyền quản trị','Administrator')}</label>{/if}<div class="flex gap-3 mt-5"><Button type="submit" variant="primary" busy={busy==='save'}>{t('Lưu tài khoản','Save account')}</Button><Button disabled={!!busy} on:click={()=>{form=null;password='';}}>{t('Huỷ','Cancel')}</Button></div></form></section>{/if}
{#if confirm}<Confirm {...confirm} {lang} busy={!!busy} onconfirm={confirm.fn} oncancel={()=>confirm=null}/>{/if}
<style>.account-avatar{width:40px;height:40px;flex:none;display:grid;place-items:center;background:#e2eee6;color:#176552;border-radius:50%;font-weight:700}.account-avatar img{border-radius:50%;object-fit:cover}</style>
